<?php
declare(strict_types=1);
require __DIR__.'/mon_reinforcement_fixture.php';
// Synthetic prices, listings and calendar. No external requests, operating statistics or orders.
$cases=[];$started=mon_monotonic();
function dp_assert(bool $ok,string $why='assertion'): void {if(!$ok)throw new RuntimeException($why);}
function dp_fault(callable $f,string $code): void {try{$f();}catch(MonFault $e){dp_assert($e->faultCode===$code,$e->faultCode);return;}throw new RuntimeException('missing '.$code);}
function dp_case(string $name,callable $f): void {global $cases;MonExecution::$active=null;MonExecution::$store=null;MonPreparation::reset();MonRun::releasePayloadCache();try{$f();$cases[]=['case'=>$name,'pass'=>true];}catch(Throwable $e){$cases[]=['case'=>$name,'pass'=>false,'error'=>$e->getMessage()];}}
function dp_copy($v) {return mon_decode(MonRun::json($v));}
function dp_bars(float $close=101.0): array {$out=[];$day=new DateTimeImmutable('2026-04-09');while(count($out)<80){if((int)$day->format('N')<=5)$out[]=[$day->format('Y-m-d'),$close-.5,$close+1,$close-1,$close,1000.0];$day=$day->modify('+1 day');}return $out;}
function dp_sources(float $close=101.0): array {
    $a=(object)['bars'=>dp_bars($close),'origin'=>(object)['source'=>'SPG_STOCKANALYSIS','price_basis'=>MonDetails::BASIS,'complete_source_window'=>true]];
    $b=(object)['bars'=>dp_bars($close),'origin'=>(object)['source'=>'NASDAQ_RAW','source_url'=>'https://api.nasdaq.com/api/quote/SYNTH/historical','source_record_sha256'=>str_repeat('a',64)]];
    $old=(object)['bars'=>dp_bars($close),'origin'=>(object)['source_url'=>'https://query1.finance.yahoo.com/v8/finance/chart/SYNTH'],'history_metadata'=>(object)['price_basis'=>MonDetails::BASIS,'checked_at'=>mon_iso()]];
    return [$a,$b,$old];
}
function dp_context($d,?string $at=null): stdClass {return(object)['source_blob_sha'=>MonRun::gitSha(MonRun::json($d)),'rendered_at'=>$at??mon_iso(),'countries'=>['KR','US','JP'],'important_ids'=>[]];}
function dp_calendar($d,bool $verified=true,bool $offDay=true): void {
    $now=time();$markets=[];
    if($verified)foreach(['KR','US','JP']as $country){$zone=MonMarket::timezone($country);$local=(new DateTimeImmutable('@'.$now))->setTimezone($zone);$sessions=[];
        foreach([-2,-1,1,2,3]as $offset){$day=$local->modify(($offset>=0?'+':'').$offset.' days')->format('Y-m-d');$open=new DateTimeImmutable($day.' '.($country==='US'?'09:30:00':'09:00:00'),$zone);$close=new DateTimeImmutable($day.' '.($country==='US'?'16:00:00':'15:30:00'),$zone);$sessions[]=(object)['market_date'=>$day,'open_at'=>$open->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z'),'close_at'=>$close->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z')];}
        if(!$offDay){$day=$local->format('Y-m-d');$open=new DateTimeImmutable($day.' 09:00:00',$zone);$close=new DateTimeImmutable($day.' 16:00:00',$zone);$sessions[]=(object)['market_date'=>$day,'open_at'=>$open->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z'),'close_at'=>$close->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z')];}
        $markets[]=(object)['country'=>$country,'timezone'=>$zone->getName(),'checked_at'=>mon_iso($now-60),'sessions'=>$sessions];}
    $d->watchlist->calendar=(object)['valid_until'=>mon_iso($now+7*86400),'markets'=>$markets];
}
function dp_batch(int $perCountry=20,bool $claim=true): array {
    $items=[];$evidence=[];$checked=mon_iso(time()-1);
    foreach(['KR','US','JP']as $country)for($i=1;$i<=$perCountry;$i++){
        $code=$country==='KR'?str_pad((string)(800000+$i),6,'0',STR_PAD_LEFT):($country==='JP'?(string)(8000+$i):'SYN'.str_pad((string)$i,2,'0',STR_PAD_LEFT));$venue=['KR'=>'KOSPI','US'=>'NASDAQ','JP'=>'TSE'][$country];$currency=['KR'=>'KRW','US'=>'USD','JP'=>'JPY'][$country];$sid=$country.'|'.$venue.'|'.$code;$eid='SYNTH-IDENTITY-'.$country.'-'.$code;
        $s=(object)['symbol_id'=>$sid,'country'=>$country,'exchange'=>$venue,'symbol'=>$code,'name'=>'Synthetic listing '.$country.' '.$i,'currency'=>$currency,'is_held'=>false,'position'=>null,'tick_size'=>$country==='US'?.01:1,'tick_rule'=>$country==='US'?'US_NMS_0.01_CURRENT':($country==='JP'?'JPX_OTHER_CURRENT':'KRX_KOSPI_CURRENT'),'source_codes'=>(object)['yahoo'=>$code.($country==='KR'?'.KS':($country==='JP'?'.T':'')),'kis'=>null,'naver'=>null],'identity_evidence_ids'=>[$eid],'candidate_origin'=>['new_in_mon'],'first_seen_at'=>'1999-01-01T00:00:00Z'];
        $items[]=(object)['symbol'=>$s,'request_id'=>'synthetic-discovery-'.$country.'-'.$code,'wait_seconds'=>120,'force_refresh'=>false];
        $e=(object)['id'=>$eid,'symbol_id'=>$sid,'source_kind'=>'independent','source_url'=>['KR'=>'https://kind.krx.co.kr/synthetic-fixture','US'=>'https://api.nasdaq.com/synthetic-fixture','JP'=>'https://www.jpx.co.jp/synthetic-fixture'][$country],'checked_at'=>$checked,'identity'=>(object)['name'=>$s->name,'country'=>$country,'symbol'=>$code,'venue'=>$venue,'currency'=>$currency]];
        if($claim)$e->claim='Synthetic fixture only; no real listing or price asserted';$evidence[]=$e;
    }return [$items,$evidence];
}
function dp_acquired(int $existing=3,bool $verified=true,bool $offDay=true): array {
    $d=reinforcement_fixture($existing);dp_calendar($d,$verified,$offDay);[$items,$evidence]=dp_batch();$r=MonDiscovery::acquire($d,dp_context($d),$items,$evidence);dp_assert($r['registered']===60,'registered '.$r['registered']);$out=mon_decode($r['files'][0]['content']);return [$d,$out,$r,$items,$evidence];
}
function dp_country($state,string $country): stdClass {foreach($state->countries as $row)if($row->country===$country)return $row;throw new RuntimeException('missing country');}

dp_case('USD half-cent boundary, CRWD 0.0005 and PLTR display precision are accepted',function(){dp_assert(MonClose::matches(100,100.005,'USD')&&MonClose::matches(185.728,185.7275,'USD')&&MonClose::matches(139.395004,139.40,'USD'));});
dp_case('One-cent material difference and sub-dollar precision remain distinct',function(){dp_assert(!MonClose::matches(100,100.01,'USD')&&!MonClose::matches(.8,.8001,'USD')&&MonClose::matches(.8,.80005,'USD'));});
dp_case('Won and yen discard only half a displayed integer unit during corroboration',function(){dp_assert(MonClose::matches(401000,401000.5,'KRW')&&MonClose::matches(3426,3426.49,'JPY')&&!MonClose::matches(3426,3427,'JPY'));});
dp_case('Invalid zero, nonfinite and unsupported currency values are rejected',function(){dp_assert(!MonClose::matches(0,.001,'USD')&&!MonClose::matches(INF,100,'USD')&&!MonClose::matches(NAN,100,'USD'));dp_fault(static function(){MonClose::matches(100,100,'EUR');},'DETAIL_CURRENCY_INVALID');});
dp_case('Whole-window near-price proof preserves both original raw arrays and hashes',function(){[$stock,$independent]=dp_sources(185.728);$independent->bars[23][4]=185.7275;$beforeA=MonRun::json($stock);$beforeB=MonRun::json($independent);$r=MonDaily::wholeWindowProof($stock,$independent,'USD');dp_assert($r->approximate_close_count===1&&$r->raw_prices_preserved&&$r->stock_bars_sha256===MonRun::digest($stock->bars)&&MonRun::json($stock)===$beforeA&&MonRun::json($independent)===$beforeB);});
dp_case('Near-price proof cannot conceal a missing or changed completed date',function(){[$a,$b]=dp_sources();$b->bars=array_slice($b->bars,0,-1);dp_fault(static function()use($a,$b){MonDaily::wholeWindowProof($a,$b);},'DETAIL_SOURCE_REPLACEMENT_UNVERIFIED');});
dp_case('Near-price proof cannot conceal a different adjustment basis',function(){[$a,$b]=dp_sources();$a->origin->price_basis='total_return_dividend_adjusted';dp_fault(static function()use($a,$b){MonDaily::wholeWindowProof($a,$b);},'DETAIL_SOURCE_REPLACEMENT_UNVERIFIED');});
dp_case('Prior-window near equality preserves fresh and old prices with no row merge',function(){[$a,$unused,$old]=dp_sources(139.40);$old->bars[42][4]=139.395004;$beforeA=MonRun::json($a);$beforeOld=MonRun::json($old);$r=MonDaily::priorWindowProof($old,$a);dp_assert($r->approximate_close_count===1&&$r->row_merge===false&&MonRun::json($a)===$beforeA&&MonRun::json($old)===$beforeOld);});
dp_case('Prior-window material or date mismatch remains unverified',function(){[$a,$unused,$old]=dp_sources();$old->bars[42][4]=101.01;dp_fault(static function()use($a,$old){MonDaily::priorWindowProof($old,$a);},'DETAIL_SOURCE_REPLACEMENT_UNVERIFIED');$old->bars[42][4]=101;$old->bars[0][0]='2026-04-08';dp_fault(static function()use($a,$old){MonDaily::priorWindowProof($old,$a);},'DETAIL_SOURCE_REPLACEMENT_UNVERIFIED');});
dp_case('Sixty primary identities preserve all thirty occupied detail request slots',function(){[$before,$out,$r]=dp_acquired(30);dp_assert(count(get_object_vars(MonDiscovery::pool($out)))===60&&count(get_object_vars(MonDetails::requests($out)))===30&&MonRun::json(MonDetails::requests($before))===MonRun::json(MonDetails::requests($out))&&MonRun::json($before->collection)===MonRun::json($out->collection)&&MonRun::json($before->analysis->results)===MonRun::json($out->analysis->results)&&$before->analysis->as_of===$out->analysis->as_of&&$r['storage']->fits);});
dp_case('Plan splits sixty saved identities into thirty fair items and thirty remaining',function(){[$before,$out]=dp_acquired();$raw=MonRun::json($out);$plan=MonDiscovery::plan($out,dp_context($out),null);dp_assert(count($plan['items'])===30&&count($plan['remaining_items'])===30&&$plan['rejected']===[]&&MonRun::json($out)===$raw);$by=[];foreach($plan['items']as $item)$by[$item->symbol->country]=($by[$item->symbol->country]??0)+1;dp_assert($by===['KR'=>10,'US'=>10,'JP'=>10]);});
dp_case('Client backdating is ignored and every saved first-seen time is the server registration time',function(){[$before,$out,$r]=dp_acquired();foreach(MonDiscovery::pool($out)as $s)dp_assert($s->first_seen_at===$r['registered_at']&&$s->first_seen_at!=='1999-01-01T00:00:00Z'&&$s->candidate_group==='new');});
dp_case('Exact replay is a no-write reuse with original first-seen and no duplicate goal credit',function(){[$before,$out,$first,$items,$evidence]=dp_acquired();$raw=MonRun::json($out);$again=MonDiscovery::acquire($out,dp_context($out),dp_copy($items),dp_copy($evidence));dp_assert($again['registered']===0&&!$again['write_required']&&MonRun::json($out)===$raw&&count($again['rows'])===60);foreach($again['rows']as $r)dp_assert($r['status']==='reuse'&&$r['first_seen_at']===$first['registered_at']);$state=MonDiscovery::counts($out,MonRun::payload($out),['full_signals'=>new stdClass()],$first['registered_at']);foreach($state->countries as $row)dp_assert($row->new_ids_identified_today===20&&$row->next_session_queued_count===20);});
dp_case('Fresh decoding of a claim-less original request replays without evidence conflict',function(){$d=reinforcement_fixture();dp_calendar($d);[$items,$evidence]=dp_batch(1,false);$original=MonRun::json((object)['items'=>$items,'evidence'=>$evidence]);$r=MonDiscovery::acquire($d,dp_context($d),$items,$evidence);$out=mon_decode($r['files'][0]['content']);$retry=mon_decode($original);$again=MonDiscovery::acquire($out,dp_context($out),$retry->items,$retry->evidence);dp_assert($again['registered']===0&&!$again['write_required']);});
dp_case('Existing symbol and alternate venue for the same country ticker are rejected',function(){$d=reinforcement_fixture();dp_calendar($d);$existing=dp_copy($d->watchlist->symbols[0]);$existing->identity_evidence_ids=['SYNTH-KNOWN'];$item=(object)['symbol'=>$existing];$e=(object)['id'=>'SYNTH-KNOWN','symbol_id'=>$existing->symbol_id,'source_kind'=>'independent','source_url'=>'https://kind.krx.co.kr/synthetic-fixture','checked_at'=>mon_iso(),'identity'=>(object)['name'=>$existing->name,'country'=>'KR','symbol'=>$existing->symbol,'venue'=>$existing->exchange,'currency'=>'KRW'],'claim'=>'Synthetic'];$r=MonDiscovery::acquire($d,dp_context($d),[$item],[$e]);dp_assert($r['registered']===0&&$r['rows'][0]['error']==='MON_DISCOVERY_ALREADY_KNOWN');$existing->exchange='KOSDAQ';$existing->symbol_id='KR|KOSDAQ|'.$existing->symbol;$e->symbol_id=$existing->symbol_id;$e->identity->venue='KOSDAQ';$r=MonDiscovery::acquire($d,dp_context($d),[$item],[$e]);dp_assert($r['registered']===0&&$r['rows'][0]['error']==='MON_DISCOVERY_ALREADY_KNOWN');});
dp_case('Missing or non-primary identity proof cannot register a new candidate',function(){$d=reinforcement_fixture();dp_calendar($d);[$items,$evidence]=dp_batch(1);$r=MonDiscovery::acquire($d,dp_context($d),[$items[0]],[]);dp_assert($r['registered']===0&&$r['rows'][0]['error']==='MON_EVIDENCE_MISSING');$evidence[0]->source_url='https://example.invalid/identity';$r=MonDiscovery::acquire($d,dp_context($d),[$items[0]],[$evidence[0]]);dp_assert($r['registered']===0&&$r['rows'][0]['error']==='MON_PRIMARY_LISTING_REQUIRED');});
dp_case('Unverified calendar stores identities but cannot assign or meet a daily quota',function(){[$before,$out,$r]=dp_acquired(3,false);foreach(MonDiscovery::pool($out)as $s)dp_assert($s->discovery_quota_date===null);foreach($r['discovery_state']->countries as $row)dp_assert($row->new_ids_identified_today===20&&$row->quota_identified_count===0&&$row->next_session_queued_count===0&&!$row->daily_goal_met&&$row->goal_status==='calendar_unverified');});
dp_case('Off-day registration queues twenty per country without rewriting discovery dates',function(){[$before,$out,$r]=dp_acquired();foreach($r['discovery_state']->countries as $row){dp_assert($row->new_ids_identified_today===20&&$row->next_session_queued_count===20&&$row->quota_identified_count===0&&!$row->daily_goal_met&&$row->goal_status==='not_due_prepared');foreach($row->identified_ids as $sid){$s=MonDiscovery::pool($out)->$sid;$firstDay=(new DateTimeImmutable($s->first_seen_at))->setTimezone(MonMarket::timezone($row->country))->format('Y-m-d');dp_assert($firstDay===$row->discovery_date&&$s->discovery_quota_date===$row->next_trading_date&&$firstDay!==$s->discovery_quota_date);}}});
dp_case('Queued identities credit exactly the next verified session and never its following day',function(){[$before,$out,$r]=dp_acquired();$p=MonRun::payload($out);foreach($r['discovery_state']->countries as $old){$zone=MonMarket::timezone($old->country);$session=(new DateTimeImmutable($old->next_trading_date.' 12:00:00',$zone))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z');$state=MonDiscovery::counts($out,$p,['full_signals'=>new stdClass()],$session);$row=dp_country($state,$old->country);dp_assert($row->new_ids_identified_today===0&&$row->quota_identified_count===20&&$row->daily_goal_met&&$row->goal_status==='met');$out->analysis->discovery_state=$state;$following=(new DateTimeImmutable($old->next_trading_date.' 12:00:00',$zone))->modify('+1 day')->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z');$after=dp_country(MonDiscovery::counts($out,$p,['full_signals'=>new stdClass()],$following),$old->country);dp_assert($after->quota_identified_count===0&&!$after->daily_goal_met&&$after->goal_status==='shortfall');}});
dp_case('Later detail registration preserves the pool first-seen timestamp',function(){[$before,$out,$r]=dp_acquired();$plan=MonDiscovery::plan($out,dp_context($out),null);$item=$plan['items'][0];$registered=MonDetails::register($out,dp_context($out),$item);dp_assert($registered['write_required']&&$registered['request']->symbol->first_seen_at===MonDiscovery::pool($out)->{$item->symbol->symbol_id}->first_seen_at&&$registered['request']->symbol->discovery_quota_date===MonDiscovery::pool($out)->{$item->symbol->symbol_id}->discovery_quota_date);});
dp_case('Historical credited session keeps zero shortfall after the discovery day advances',function(){[$before,$out,$r]=dp_acquired();$p=MonRun::payload($out);$old=dp_country($r['discovery_state'],'US');$zone=MonMarket::timezone('US');$day=(new DateTimeImmutable($old->next_trading_date.' 12:00:00',$zone))->setTimezone(new DateTimeZone('UTC'));$out->analysis->discovery_state=MonDiscovery::counts($out,$p,['full_signals'=>new stdClass()],$day->format('Y-m-d\TH:i:s\Z'));$state=MonDiscovery::counts($out,$p,['full_signals'=>new stdClass()],$day->modify('+1 day')->format('Y-m-d\TH:i:s\Z'));$found=false;foreach($state->previous_days as $row)if($row->country==='US'&&$row->discovery_date===$old->next_trading_date){$found=true;dp_assert($row->quota_identified_count===20&&$row->shortfall===0&&$row->daily_goal_met&&$row->goal_status==='met','credited historical shortfall '.mon_get($row,'shortfall'));}dp_assert($found);});
dp_case('Historical off-day preparation keeps its not-due status and zero shortfall',function(){[$before,$out,$r]=dp_acquired();$old=dp_country($r['discovery_state'],'US');$zone=MonMarket::timezone('US');$day=(new DateTimeImmutable($old->next_trading_date.' 12:00:00',$zone))->setTimezone(new DateTimeZone('UTC'));$state=MonDiscovery::counts($out,MonRun::payload($out),['full_signals'=>new stdClass()],$day->format('Y-m-d\TH:i:s\Z'));$found=false;foreach($state->previous_days as $row)if($row->country==='US'&&$row->discovery_date===$old->discovery_date){$found=true;dp_assert($row->shortfall===0&&!$row->daily_goal_met&&$row->goal_status==='not_due_prepared','off-day historical status '.mon_get($row,'goal_status'));}dp_assert($found);});
dp_case('Batched request registration matches sequential results and retains pool overflow',function(){[$before,$out]=dp_acquired();$context=dp_context($out);$plan=MonDiscovery::plan($out,$context,null);$batch=MonDetails::registerMany($out,$context,$plan['items']);$batched=mon_decode($batch['files'][0]['content']);$sequential=dp_copy($out);$statuses=[];foreach($plan['items']as $item)try{$r=MonDetails::register($sequential,$context,$item);$statuses[]=$r['status'];if($r['write_required'])$sequential=mon_decode($r['files'][0]['content']);}catch(MonFault $e){$statuses[]='rejected';}dp_assert(array_column($batch['requests'],'status')===$statuses&&MonRun::json($batched)===MonRun::json($sequential));dp_assert(count(get_object_vars(MonDetails::requests($batched)))===30&&count(get_object_vars(MonDiscovery::pool($batched)))===60);$after=MonDiscovery::plan($batched,dp_context($batched),[]);dp_assert(count($after['items'])===30&&count($after['remaining_items'])===3&&count(array_filter($statuses,static function($s){return $s==='rejected';}))===3);});
dp_case('An invalid batch item does not prevent independent valid items from being queued',function(){[$before,$out]=dp_acquired();$context=dp_context($out);$items=array_slice(MonDiscovery::plan($out,$context,null)['items'],0,3);$items[1]=dp_copy($items[1]);$items[1]->symbol->is_held=true;$rawCollection=MonRun::json($out->collection);$batch=MonDetails::registerMany($out,$context,$items);dp_assert(array_column($batch['requests'],'status')===['queued','rejected','queued']&&$batch['requests'][1]['error']==='DETAIL_ENTRY_SYMBOL_INVALID'&&$batch['write_required']);$saved=mon_decode($batch['files'][0]['content']);dp_assert(count(get_object_vars(MonDetails::requests($saved)))===5&&MonRun::json($saved->collection)===$rawCollection&&count(get_object_vars(MonDiscovery::pool($saved)))===60);});

$bad=array_values(array_filter($cases,static function($r){return !$r['pass'];}));$report=['kind'=>'targeted_discovery_precision_php_tests','processor_version'=>MON_VERSION,'php_version'=>PHP_VERSION,'case_count'=>count($cases),'passed'=>count($cases)-count($bad),'failed'=>count($bad),'elapsed_seconds'=>round(mon_monotonic()-$started,6),'peak_bytes'=>memory_get_peak_usage(true),'external_requests'=>0,'operating_statistics_modified'=>false,'orders'=>0,'fixtures'=>'Synthetic listings, prices and calendar only; official-host URLs are inert fixtures.','cases'=>$cases];file_put_contents(__DIR__.'/mon_discovery_precision_tests.json',mon_json($report));echo mon_json(['case_count'=>count($cases),'passed'=>$report['passed'],'failed'=>$bad,'elapsed_seconds'=>$report['elapsed_seconds'],'peak_bytes'=>$report['peak_bytes']]);exit($bad?1:0);
